// node tools/browser_vectors.mjs <chromium|firefox|webkit> [executablePath]
// Assumes the repository root is served at http://localhost:8766/ and inputs were
// generated by tools/prepare_vec_tmp.sh. Runs the items one at a time (timeout per
// item) and prints each result as it comes, so a slow browser shows its progress.
import { chromium, firefox, webkit } from 'playwright';
const kind = process.argv[2];
const browserType = { chromium, firefox, webkit }[kind];
const opts = process.argv[3] ? { executablePath: process.argv[3] } : {};
const browser = await browserType.launch(opts);
const page = await browser.newPage();
page.setDefaultTimeout(30 * 60 * 1000); // per item
await page.goto('http://localhost:8766/web/vectors/index.html?driver');
await page.waitForFunction(() => window.__items !== undefined, null, { timeout: 120 * 1000 });
const names = await page.evaluate(() => window.__items);
console.log(kind, browser.version(), `${names.length} items`);
const results = [];
for (let i = 0; i < names.length; i++) {
  const r = await page.evaluate(i => window.__runItem(i), i);
  console.log(`${r.name}\t${r.ok ? 'ok' : 'MISMATCH ' + r.got}\t${r.seconds.toFixed(1)} s`);
  results.push(r);
}
await browser.close();
const ok = results.every(r => r.ok);
console.log(ok ? 'ALL OK' : 'FAILED');
if (!ok) process.exit(1);
